def solve_1d_max_k(N, s):
    # L_i = [max(0, i-s+1), min(i, N-s)]
    # c(i, j) = max(0, min(b_i, b_j) - max(a_i, a_j) + 1)
    # we want to maximize k = max_V count((i, j) such that c(i, j) = V > 0)
    M = N - s
    a = [max(0, i - s + 1) for i in range(N)]
    b = [min(i, M) for i in range(N)]

    counts = {}
    for i in range(N):
        for j in range(N):
            val = max(0, min(b[i], b[j]) - max(a[i], a[j]) + 1)
            if val > 0:
                counts[val] = counts.get(val, 0) + 1
    return max(counts.values()) if counts else 0

