def solve_1d_small(N, s):
    # Try all subsets J of {0, ..., N-s}
    # Since N-s is small, we can use bitmask.
    limit = N - s
    max_k = 0
    for i in range(1 << (limit + 1)):
        J = []
        for bit in range(limit + 1):
            if (i >> bit) & 1:
                J.append(bit)

        # Calculate k
        current_k = 0
        m = len(J)
        if m == 0:
            current_k = 0
        else:
            # j_{-1} = -s, j_{m} = J[m-1], j_{m+1} = N
            # Wait, the indices were j_0, ..., j_{m-1}.
            # So let's use a list j where j_0, ..., j_{m-1} are the elements.
            j = J
            num_j = len(j)
            for k in range(num_j):
                prev_j = j[k-1] if k > 0 else -s
                curr_j = j[k]
                next_j = j[k+1] if k < num_j - 1 else N

                start = max(curr_j, prev_j + s)
                end = min(curr_j + s - 1, next_j - 1)
                if end >= start:
                    current_k += (end - start + 1)
        max_k = max(max_k, current_k)
    return max_k

